        </h2>
        <h3>Current query</h3>
        <pre>{JSON.stringify(propertyFilterProps.query, null, 2)}</pre>
        <table style={{ borderCollapse: 'collapse', width: '100%', marginTop: 8 }}>
          <thead>
            <tr>
              <th style={{ border: '1px solid #ccc', padding: 8, textAlign: 'left' }}>Name</th>
